#!/usr/bin/env node
/**
 * Bundles the advisor's knowledge (public, numbers-free repo files) into
 * lib/content.generated.ts so the service is self-contained on Vercel.
 *
 * Source of truth stays in the Istri repo (knowledge-base/, decisions/,
 * docs/standards/, .claude/skills/loonars-mentor/). Run after editing those:
 *   npm run sync-content
 * The generated file is committed; tests/content.test.ts fails if it drifts.
 * With --if-present (prebuild) it is a no-op when the sources are not
 * available (e.g. a build that only sees the service/ folder).
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const repo = path.resolve(here, "..", "..");
const out = path.resolve(here, "..", "lib", "content.generated.ts");

const SOURCES = [
  { key: "mentor", files: [".claude/skills/loonars-mentor/SKILL.md"] },
  { key: "standar", files: ["docs/standards/data-labels.md", "docs/standards/decision-review-policy.md"] },
  { key: "knowledge", dir: "knowledge-base" },
  { key: "keputusan", dir: "decisions", skip: ["_template.md"] },
];

export function collect() {
  const result = {};
  for (const s of SOURCES) {
    const files = s.files ?? walk(path.join(repo, s.dir)).map((f) => path.relative(repo, f));
    result[s.key] = files
      .filter((f) => !(s.skip ?? []).includes(path.basename(f)))
      .sort()
      .map((f) => ({ path: f, text: fs.readFileSync(path.join(repo, f), "utf8") }));
  }
  return result;
}

function walk(dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((e) => {
    const p = path.join(dir, e.name);
    return e.isDirectory() ? walk(p) : e.name.endsWith(".md") ? [p] : [];
  });
}

export function render(content) {
  return (
    "// GENERATED by scripts/sync-content.mjs — do not edit by hand.\n" +
    "// Source: Istri repo knowledge-base/, decisions/, docs/standards/, .claude/skills/loonars-mentor/.\n" +
    "export interface ContentFile { path: string; text: string }\n" +
    `export const CONTENT: Record<"mentor" | "standar" | "knowledge" | "keputusan", ContentFile[]> = ${JSON.stringify(content, null, 1)};\n`
  );
}

const isMain = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const ifPresent = process.argv.includes("--if-present");
  if (!fs.existsSync(path.join(repo, "knowledge-base"))) {
    if (ifPresent) {
      console.log("sync-content: sources not present, keeping committed lib/content.generated.ts");
      process.exit(0);
    }
    console.error("sync-content: knowledge-base/ not found at", repo);
    process.exit(1);
  }
  fs.writeFileSync(out, render(collect()));
  console.log("sync-content: wrote", path.relative(process.cwd(), out));
}
